 const variants=[['Main deck','Palette and brushwork reference',e.baseline,null],['Original signature','Archived full-color illustration',e.card,null],['A · card palette','Tonal painting, minimal color variation',e.card,0],['B · signature accent','Same palette, a few contrasting strokes',e.card,1]];
